    parser.add_argument(
        "--op", 
        choices=[
            "add", "subtract", "multiply", "divide", "power", "modulo", 
            "evaluate", "memory_store", "memory_recall", "memory_clear", 
            "get_history", "clear_history", "list_plugins", "run_plugin"
        ], 
        required=True,
        help="The operation to perform"
    )

    # Arguments for standard arithmetic (a, b)
    parser.add_argument("--a", type=float, help="First operand")
    parser.add_argument("--b", type=float, help="Second operand")

    # Arguments for expression evaluation or plugin name
    parser.add_argument("--expr", type=str, help="Mathematical expression for evaluate")
    parser.add_argument("--plugin", type=str, help="Plugin name for run_plugin")

    args = parser.parse_args()

    try:
        if args.op == "add":
            print(f"Result: {calc.add(args.a, args.b)}")
        elif args.op == "subtract":
            print(f"Result: {calc.subtract(args.a, args.b)}")
        elif args.op == "multiply":
            print(f"Result: {calc.multiply(args.a, args.b)}")
        elif args.op == "divide":
            print(f"Result: {calc.divide(args.a, args.b)}")
        elif args.op == "power":
            print(f"Result: {calc.power(args.a, args.b)}")
        elif args.op == "modulo":
            print(f"Result: {calc.modulo(args.a, args.b)}")
        elif args.op == "evaluate":
            print(f"Result: {calc.evaluate(args.expr)}")
        elif args.op == "memory_store":
            calc.memory_store(args.a)
            print("Value stored in memory.")
        elif args.op == "memory_recall":
            print(f"Memory: {calc.memory_recall()}")
        elif args.op == "memory_clear":
            calc.memory_clear()
            print("Memory cleared.")
        elif args.op == "get_history":
            print(f"History: {calc.get_history()}")
        elif args.op == "clear_history":
            calc.clear_history()
            print("History cleared.")
        elif args.op == "list_plugins":
            print(f"Plugins: {calc.list_plugins()}")
        elif args.op == "run_plugin":
            # Note: passing arbitrary args is complex via CLI, simplified here
            print(f"Result: {calc.run_plugin(args.plugin, args.a, args.b)}")

    except ValueError as e:
